using System;using System.IO;using System.Linq;using System.Net;using System.Collections.Generic;using System.Diagnostics;using System.Threading.Tasks;
namespace ContourWatch {
public static class AgentUpdater {
 static DateTime next=DateTime.MinValue;static Task job;public static volatile string Status="Автообновление выключено";
 public static void Poll(Dictionary<string,object> config,Dictionary<string,object> policy){if(!policy.ContainsKey("enabled")||!Convert.ToBoolean(policy["enabled"])){Status="Автообновление выключено";return;}if(DateTime.UtcNow<next||job!=null&&!job.IsCompleted)return;int start=Convert.ToInt32(policy["start"]),end=Convert.ToInt32(policy["end"]),hour=DateTime.UtcNow.Hour;if(start<end?(hour<start||hour>=end):(hour<start&&hour>=end)){Status="Ожидание окна обновления";return;}next=DateTime.UtcNow.AddMinutes(60+new Random().Next(0,15));job=Task.Factory.StartNew(()=>Check(config));}
 static void Check(Dictionary<string,object> config){string stage=null;bool launched=false;try{Status="Проверка выпуска";var reply=Agent.Post(config,"/api/update/check",Agent.Obj());if(!reply.ContainsKey("available")||!Convert.ToBoolean(reply["available"])){Status="Новых выпусков нет";return;}string text=Convert.ToString(reply["manifest"]),signature=Convert.ToString(reply["signature"]);var artifact=UpdateSecurity.Verify(text,signature,"windows-x64",Agent.Version);if(artifact==null){Status="Установлена актуальная версия";return;}
  string updates=Path.Combine(Agent.Root,"updates");Directory.CreateDirectory(updates);string blocked=Path.Combine(updates,"blocked-release.txt");if(File.Exists(blocked)&&File.ReadAllText(blocked).Trim()==Convert.ToString(artifact["tag"])){Status="Неудачный выпуск заблокирован: "+artifact["tag"];return;}if(new DirectoryInfo(updates).EnumerateFiles("*",SearchOption.AllDirectories).Sum(f=>f.Length)>300L*1024*1024){Status="Нужно очистить архивы предыдущих обновлений";return;}
  stage=Path.Combine(updates,"stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);string file=Path.Combine(stage,Convert.ToString(artifact["name"]));var request=(HttpWebRequest)WebRequest.Create(UpdateSecurity.Url(artifact));request.Timeout=20000;request.ReadWriteTimeout=15000;request.Proxy=null;var clock=Stopwatch.StartNew();long size=0;using(var response=(HttpWebResponse)request.GetResponse())using(var input=response.GetResponseStream())using(var output=File.Create(file)){var buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){size+=n;if(size>Convert.ToInt64(artifact["size"])||clock.Elapsed>TimeSpan.FromMinutes(5))throw new IOException("update download limit");output.Write(buffer,0,n);}}
  if(size!=Convert.ToInt64(artifact["size"])||UpdateSecurity.Digest(file)!=Convert.ToString(artifact["sha256"]))throw new IOException("update digest");
  var control=Agent.Post(config,"/api/control",Agent.Obj("version",Agent.Version));var policy=(Dictionary<string,object>)control["updates"];int start=Convert.ToInt32(policy["start"]),end=Convert.ToInt32(policy["end"]),hour=DateTime.UtcNow.Hour;var again=Agent.Post(config,"/api/update/check",Agent.Obj());if(!Convert.ToBoolean(policy["enabled"])||(start<end?(hour<start||hour>=end):(hour<start&&hour>=end))||!Convert.ToBoolean(again["available"])||Convert.ToString(again["manifest"])!=text){Status="Установка отложена политикой";return;}
  File.WriteAllText(Path.Combine(stage,"manifest.json"),text,new System.Text.UTF8Encoding(false));File.WriteAllText(Path.Combine(stage,"manifest.sig"),signature,new System.Text.UTF8Encoding(false));string helper=Path.Combine(stage,"ContourUpdater.exe");File.Copy(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ContourUpdater.exe"),helper);Status="Проверено. Установка "+artifact["version"];Process.Start(new ProcessStartInfo(helper,"\""+stage+"\""){UseShellExecute=false,CreateNoWindow=true});launched=true;
 }catch(Exception e){Status="Обновление отложено: "+e.GetType().Name;AgentLog.Write("warning","updater","update.failed",e.GetType().Name);}finally{if(stage!=null&&!launched){try{string allowed=Path.GetFullPath(Path.Combine(Agent.Root,"updates"))+Path.DirectorySeparatorChar;if(Path.GetFullPath(stage).StartsWith(allowed,StringComparison.OrdinalIgnoreCase)&&(File.GetAttributes(stage)&FileAttributes.ReparsePoint)==0)Directory.Delete(stage,true);}catch{}}}}
}
}
